def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    recent_start = max(0, n - 5)
    opp_recent_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            opp_recent_d += 1

    consec_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_d += 1
        else:
            break

    punish = 0
    success = 0
    unprompted = 0
    for i in range(1, n):
        prev_my = history[i - 1][0]
        opp = history[i][1]
        if prev_my == 'D':
            if opp == 'D':
                punish += 1
            else:
                success += 1
        else:
            if opp == 'D':
                unprompted += 1

    remaining = 100 - n

    hostile = (
        opp_d * 2 > n or
        opp_recent_d >= 4 or
        consec_opp_d >= 3 or
        opp_d >= max(2, n - 2)
    )
    if unprompted >= 2 and opp_d >= max(2, n // 5):
        hostile = True

    if last_opp == 'D':
        if hostile or consec_opp_d >= 2:
            return 'D'
        if my_d == 0:
            return 'D'
        if punish > 0 and opp_d <= max(1, n // 5):
            return 'C'
        return 'D'

    if hostile:
        return 'D'

    if opp_d == 0 and unprompted == 0 and punish == 0:
        if success >= 6 and n >= 30:
            return 'D'
        if success >= 3 and remaining <= 35:
            return 'D'
        if success >= 1 and remaining <= 12:
            return 'D'
        if n >= 10 and last_my == 'C' and my_d <= 12:
            return 'D'
        return 'C'

    if (
        punish == 0 and
        opp_d <= max(2, n // 5) and
        unprompted <= max(2, n // 5)
    ):
        if success >= 6 and n >= 45 and opp_d * 3 <= n:
            return 'D'
        if success >= 3 and remaining <= 35:
            return 'D'
        if success >= 1 and remaining <= 15:
            return 'D'
        if n >= 15 and last_my == 'C' and my_d <= 8:
            return 'D'

    return 'C'
